begin;

-- Authorial V5 content is compiled for review but remains inactive and unaligned.
-- No student can receive it until separate pedagogical and publication gates pass.
do $seed_question_first_content_v5$
declare
  v_catalog_id uuid;
  v_skill_id uuid;
  v_lesson_id uuid;
  v_set_id uuid;
  v_question_id uuid;
  v_question record;
begin
  select id into v_catalog_id
    from public.learning_curriculum_catalogs
   where code = 'TECESCOLA_CORE' and version = '1.0'
   limit 1;
  if v_catalog_id is null then raise exception 'V5_CONTENT_CATALOG_MISSING'; end if;
  select id into v_skill_id
    from public.learning_curriculum_skills
   where catalog_id = v_catalog_id and code = 'SOCIOLOGY_ANALYZE_INEQUALITY_DATA';
  if v_skill_id is null then raise exception 'V5_CONTENT_SKILL_MISSING'; end if;

  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 6, 'Ler dados de desigualdade sem extrapolar', 'Leia população, período, definição e denominador; escolha a comparação adequada; examine distribuição e método; descreva o padrão antes de explicar suas causas.', 'Use um roteiro em cinco passos. Primeiro, identifique quem foi observado, em que período e como cada variável foi definida. Segundo, leia unidade e denominador: uma contagem não é uma taxa, e grupos de tamanhos diferentes devem ser comparados por proporções quando a pergunta tratar de participação relativa. Terceiro, escolha a operação adequada: diferença em pontos percentuais é uma subtração; variação relativa divide a diferença pelo valor inicial. Quarto, observe a distribuição: média, mediana e coeficientes como o Gini respondem a perguntas diferentes, e nenhum valor agregado descreve automaticamente cada pessoa. Quinto, formule uma conclusão descritiva limitada à amostra e ao período. Para propor uma causa, investigue mecanismos, seleção, não resposta e explicações concorrentes. Desigualdades observadas não devem ser explicadas apenas por esforço individual sem evidência que sustente essa hipótese.',
    'Exemplo inteiramente fictício: em um levantamento, 18 de 60 famílias do grupo A e 24 de 80 do grupo B utilizaram um serviço. As contagens são 18 e 24, mas as taxas são 30% nos dois grupos. O dado permite descrever igualdade das proporções observadas nesse recorte; não informa por que as famílias usaram o serviço nem permite generalizar sem conhecer a seleção e o período da pesquisa.', array['Anote população, período, definição, unidade e denominador antes de calcular.', 'Declare se está comparando contagens, taxas, diferenças absolutas ou variações relativas.', 'Escreva uma frase descritiva e outra sobre o limite da inferência.', 'Para explicar causas, procure comparação adequada, temporalidade e mecanismos; não atribua diferenças apenas a esforço individual.']::text[], 32, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-sociology-inequality-data-wave3","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Frações e porcentagens simples","Leitura de tabelas","Subtração e divisão"],"key_concepts":["Taxa ou proporção: numerador dividido pelo denominador explicitamente definido.","Ponto percentual: diferença entre duas porcentagens; variação relativa: diferença dividida pela base inicial.","Média, mediana e Gini resumem aspectos distintos; a medida não substitui a leitura de escopo e distribuição.","Associação descreve variação conjunta; inferência causal requer desenho e evidências adicionais.","Representatividade depende do processo de seleção, cobertura e não resposta, não só do tamanho da amostra."],"progression":[{"stage":"FOUNDATION","focus":"Ler denominadores e comparar proporções em tabelas curtas.","questionIds":["v5-sociology-inequality-probe-01","v5-sociology-inequality-probe-02","v5-sociology-inequality-probe-03","v5-sociology-inequality-probe-04","v5-sociology-inequality-practice-01","v5-sociology-inequality-practice-02","v5-sociology-inequality-practice-03","v5-sociology-inequality-practice-04","v5-sociology-inequality-practice-05","v5-sociology-inequality-practice-06"]},{"stage":"COMPARISON","focus":"Distinguir taxas, pontos percentuais, variação relativa e resumos distributivos.","questionIds":["v5-sociology-inequality-practice-07","v5-sociology-inequality-practice-08","v5-sociology-inequality-practice-09","v5-sociology-inequality-practice-10","v5-sociology-inequality-practice-11","v5-sociology-inequality-practice-12","v5-sociology-inequality-transfer-01","v5-sociology-inequality-transfer-02","v5-sociology-inequality-transfer-03"]},{"stage":"INFERENCE_LIMITS","focus":"Avaliar amostragem, comparabilidade, causalidade e limites de indicadores.","questionIds":["v5-sociology-inequality-transfer-04","v5-sociology-inequality-transfer-05","v5-sociology-inequality-transfer-06","v5-sociology-inequality-transfer-07","v5-sociology-inequality-transfer-08","v5-sociology-inequality-lock-01","v5-sociology-inequality-lock-02","v5-sociology-inequality-lock-03","v5-sociology-inequality-lock-04","v5-sociology-inequality-lock-05","v5-sociology-inequality-lock-06"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Recuperar os conceitos em tabelas, períodos e contextos variados.","questionIds":["v5-sociology-inequality-review-01","v5-sociology-inequality-review-02","v5-sociology-inequality-review-03","v5-sociology-inequality-review-04","v5-sociology-inequality-review-05","v5-sociology-inequality-review-06","v5-sociology-inequality-review-07","v5-sociology-inequality-review-08","v5-sociology-inequality-review-09","v5-sociology-inequality-review-10"]}],"micro_explanations":[{"trigger":"DENOMINATOR_FIRST","text":"Antes de dividir, diga quem compõe o total. A taxa é numerador ÷ denominador do mesmo grupo."},{"trigger":"PERCENTAGE_POINTS","text":"De 28% para 35% há 7 pontos percentuais; o aumento relativo usa 28% como base."},{"trigger":"DISTRIBUTION_SUMMARY","text":"Média e mediana podem divergir quando há valores extremos; examine a distribuição."},{"trigger":"GINI_SCOPE","text":"O Gini resume desigualdade relativa da distribuição considerada; não é renda média nem taxa de pobreza."},{"trigger":"ASSOCIATION_NOT_CAUSATION","text":"Uma associação descreve um padrão. Causas exigem comparação, mecanismo e análise de explicações concorrentes."},{"trigger":"SAMPLE_COVERAGE","text":"Pergunte quem podia ser selecionado e quem ficou de fora antes de generalizar."}],"remediations":[{"id":"MATCH_NUMERATOR_DENOMINATOR","misconception":"DENOMINATOR_MISMATCH","prompt":"Circule o grupo, sublinhe seu total e forme a fração participantes ÷ total daquele mesmo grupo."},{"id":"SEPARATE_CHANGE_MEASURES","misconception":"PERCENTAGE_POINT_CONFUSION","prompt":"Calcule primeiro a subtração em pontos percentuais; depois, se pedido, divida a diferença pelo valor inicial."},{"id":"READ_DISTRIBUTION","misconception":"MEAN_MEDIAN_EXTREME_CONFUSED","prompt":"Ordene os valores para encontrar a mediana, calcule a média e observe o efeito dos extremos."},{"id":"DESCRIBE_BEFORE_CAUSING","misconception":"CORRELATION_AS_CAUSATION","prompt":"Complete duas frases: “Os dados mostram…” e “Ainda não sabemos se…”. Liste ao menos uma explicação concorrente."},{"id":"AUDIT_SAMPLE_SCOPE","misconception":"SELF_SELECTION_IGNORED","prompt":"Registre como as pessoas foram selecionadas, quem não respondeu e qual população pode ser descrita com segurança."},{"id":"SEPARATE_INDICATORS","misconception":"GINI_MEASURE_MISREAD","prompt":"Escreva o que o indicador mede e o que não mede; procure uma medida específica para a pergunta restante."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"Síntese de Indicadores Sociais: conceitos, métodos e tabelas","publisher":"Instituto Brasileiro de Geografia e Estatística (IBGE)","url":"https://www.ibge.gov.br/estatisticas/sociais/populacao/9221-sintese-de-indicadores-sociais","accessedOn":"2026-10-13","supports":["Escopo, conceitos e metadados necessários para interpretar indicadores sociais de educação, trabalho, rendimento, saúde e condições de vida."],"use":"Referência metodológica; os cenários, números e itens do pacote são fictícios e autorais."},{"title":"Trabalho e Rendimento: resultados preliminares da amostra — conceito do índice de Gini","publisher":"Instituto Brasileiro de Geografia e Estatística (IBGE)","url":"https://agenciadenoticias.ibge.gov.br/media/com_mediaibge/arquivos/53fde9c24f6d8df3108c83f6378e018f.pdf","accessedOn":"2026-10-13","supports":["Definição e direção de leitura do coeficiente de Gini como medida de desigualdade da distribuição."],"use":"Consulta conceitual; nenhum resultado numérico real foi reproduzido nos exercícios."}],"copyright_note":"Questões, tabelas, valores fictícios, exemplos e feedback foram escritos de forma autoral. As fontes sustentam interpretação de indicadores, não validam mapeamento oficial da habilidade interna. Mapeamento BNCC e revisão pedagógica humana permanecem pendentes.","source_question_feedback":[{"questionId":"v3-sociology-sociology_institutions-4","hint":"Observe quais condições concretas aparecem no enunciado e como elas alteram o acesso.","errorFocus":"Reduzir desigualdade observada a esforço individual."},{"questionId":"v3-sociology-sociology_institutions-10","hint":"Confira quem foi incluído na pesquisa e se a amostra representa a população sobre a qual se quer falar.","errorFocus":"Generalizar uma amostra de uma rede social para toda a população."},{"questionId":"v93-soc-inequality-01","hint":"Calcule cada proporção usando o total do grupo correspondente.","errorFocus":"Comparar contagens quando os denominadores diferem."},{"questionId":"v93-soc-inequality-02","hint":"Separe a diferença observada de qualquer explicação causal.","errorFocus":"Atribuir causa única a uma associação."},{"questionId":"v93-soc-inequality-03","hint":"Leia a população, o período e a definição do indicador antes de compará-lo.","errorFocus":"Comparar medidas com escopos distintos como se fossem iguais."},{"questionId":"v93-soc-inequality-04","hint":"Identifique quem está no denominador e o que a porcentagem representa.","errorFocus":"Interpretar um percentual sem seu universo de referência."},{"questionId":"v93-soc-inequality-05","hint":"Uma média descreve o centro aritmético, mas não toda a distribuição.","errorFocus":"Tomar média como experiência de cada pessoa."},{"questionId":"v93-soc-inequality-06","hint":"Observe como os dados foram coletados e quem não teve chance de participar.","errorFocus":"Supor que o tamanho da amostra elimina viés de seleção."},{"questionId":"v93-soc-inequality-07","hint":"Diferencie uma diferença em unidades percentuais de uma variação relativa.","errorFocus":"Confundir pontos percentuais com porcentagem relativa."},{"questionId":"v93-soc-inequality-08","hint":"Compare os grupos dentro do mesmo período e com a mesma definição.","errorFocus":"Ignorar mudança de composição ou de metodologia."},{"questionId":"v93-soc-inequality-09","hint":"A medida agregada não determina o valor de cada integrante.","errorFocus":"Inferir características individuais a partir do total do grupo."},{"questionId":"v93-soc-inequality-10","hint":"Uma associação sugere uma pergunta; procure desenho e evidências para avaliar mecanismo.","errorFocus":"Transformar correlação em causalidade."},{"questionId":"v93-soc-inequality-11","hint":"Verifique como os grupos foram definidos e quais casos ficaram de fora.","errorFocus":"Tratar categorias da pesquisa como grupos internamente homogêneos."},{"questionId":"v93-soc-inequality-12","hint":"Diga exatamente o que a tabela permite afirmar e o que continua desconhecido.","errorFocus":"Extrapolar além dos dados observados."},{"questionId":"v93-soc-inequality-13","hint":"Compare taxas ou proporções quando os grupos têm tamanhos diferentes.","errorFocus":"Escolher o maior total como maior incidência."},{"questionId":"v93-soc-inequality-14","hint":"Considere média, mediana e dispersão como resumos diferentes.","errorFocus":"Tratar uma média como descrição completa da distribuição."},{"questionId":"v93-soc-inequality-15","hint":"Consulte o método e a unidade da medida antes de comparar duas séries.","errorFocus":"Supor comparabilidade pelo nome igual do indicador."},{"questionId":"v93-soc-inequality-16","hint":"A taxa de resposta e o perfil de quem respondeu podem afetar a estimativa.","errorFocus":"Tratar não resposta como aleatória sem evidência."},{"questionId":"v93-soc-inequality-17","hint":"Uma mudança temporal, sozinha, não elimina explicações concorrentes.","errorFocus":"Afirmar que o evento anterior causou a mudança posterior."},{"questionId":"v93-soc-inequality-18","hint":"Descreva o padrão primeiro; para explicar, são necessárias evidências adicionais.","errorFocus":"Usar explicação moral ou individual sem suporte nos dados."},{"questionId":"v93-soc-inequality-19","hint":"A conclusão deve ficar dentro do grupo e do período pesquisados.","errorFocus":"Generalizar resultado local para toda a população."},{"questionId":"v93-soc-inequality-20","hint":"Uma média igual pode coexistir com distribuições e acessos muito diferentes.","errorFocus":"Reduzir dimensões de desigualdade a um único indicador."}],"objective":"Analisar proporções, diferenças e distribuições sociais identificando o que os dados sustentam e sem atribuir resultados apenas ao esforço individual.","common_mistake":"Ver um total maior e concluir que a taxa ou a desigualdade também é maior, sem conferir o denominador e a distribuição.","estimated_minutes":32}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 6
     and metadata->>'content_id' = 'v5-sociology-inequality-data-wave3' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-sociology-inequality-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"COMMUNITY_CENTRE_RATE","statement":"Em um levantamento fictício, 24 de 80 pessoas do grupo A e 36 de 120 do grupo B participaram de uma oficina. Qual comparação é correta?","options":["O grupo B teve taxa 12 pontos percentuais maior.","O grupo A teve taxa maior porque 24 é menor que 36.","Os dois grupos tiveram participação de 30%.","Os dados provam que os grupos tinham o mesmo tamanho."],"correctAnswer":"Os dois grupos tiveram participação de 30%.","explanation":"24/80 = 30% e 36/120 = 30%. As contagens diferem porque os denominadores também diferem.","errorFocus":"Comparar contagens brutas sem considerar o tamanho de cada grupo.","hint":"Divida cada número de participantes pelo total do próprio grupo.","misconceptions":{"O grupo B teve taxa 12 pontos percentuais maior.":["COUNT_CONFUSED_WITH_RATE"],"O grupo A teve taxa maior porque 24 é menor que 36.":["COUNT_CONFUSED_WITH_RATE"],"Os dados provam que os grupos tinham o mesmo tamanho.":["COUNT_CONFUSED_WITH_RATE"]},"position":1},{"id":"v5-sociology-inequality-probe-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":"GINI_DIRECTION","statement":"Uma tabela hipotética registra Gini 0,42 no território X e 0,36 no Y, para a mesma medida e período. O que ela permite afirmar?","options":["A desigualdade medida é menor em Y; isso não informa, por si só, qual território tem maior renda média.","Y tem necessariamente renda média maior.","X tem menor desigualdade porque seu índice é maior.","Os valores indicam a porcentagem de pessoas pobres."],"correctAnswer":"A desigualdade medida é menor em Y; isso não informa, por si só, qual território tem maior renda média.","explanation":"Na escala do Gini, valores mais próximos de zero indicam menor desigualdade na distribuição medida. O índice não é renda média nem taxa de pobreza.","errorFocus":"Tratar um indicador de distribuição como se medisse nível de renda ou pobreza.","hint":"Identifique primeiro o que o indicador mede e compare sua direção.","misconceptions":{"Y tem necessariamente renda média maior.":["GINI_MEASURE_MISREAD"],"X tem menor desigualdade porque seu índice é maior.":["GINI_MEASURE_MISREAD"],"Os valores indicam a porcentagem de pessoas pobres.":["GINI_MEASURE_MISREAD"]},"position":2},{"id":"v5-sociology-inequality-probe-03","purpose":"PROBE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"VOLUNTARY_ONLINE_SAMPLE","statement":"Uma consulta fictícia sobre transporte recebe respostas de 600 pessoas que escolheram participar por um link aberto em uma rede social. Qual conclusão é mais cuidadosa?","options":["A maioria de todos os moradores tem a mesma opinião.","O grande número de respostas elimina qualquer viés de seleção.","A consulta prova que a falta de transporte causou as opiniões.","As respostas descrevem participantes; a amostra pode não representar todos os moradores."],"correctAnswer":"As respostas descrevem participantes; a amostra pode não representar todos os moradores.","explanation":"A autoseleção pode atrair pessoas com experiências ou interesse específicos. O tamanho não corrige automaticamente a falta de amostragem representativa.","errorFocus":"Confundir muitas respostas voluntárias com uma amostra representativa.","hint":"Pergunte como as pessoas foram selecionadas, não apenas quantas responderam.","misconceptions":{"A maioria de todos os moradores tem a mesma opinião.":["SELF_SELECTION_IGNORED"],"O grande número de respostas elimina qualquer viés de seleção.":["SELF_SELECTION_IGNORED"],"A consulta prova que a falta de transporte causou as opiniões.":["SELF_SELECTION_IGNORED"]},"position":3},{"id":"v5-sociology-inequality-probe-04","purpose":"PROBE","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"EDUCATION_INCOME_ASSOCIATION","statement":"Em uma pesquisa hipotética, anos de estudo e rendimento aparecem associados. Qual leitura separa descrição de causalidade?","options":["A associação prova que cada ano adicional causou o mesmo aumento de renda.","Os dados mostram associação; para atribuir causa, é preciso investigar mecanismos e explicações concorrentes.","O rendimento causou necessariamente todos os anos de estudo observados.","Não há relação possível porque a tabela contém dois indicadores."],"correctAnswer":"Os dados mostram associação; para atribuir causa, é preciso investigar mecanismos e explicações concorrentes.","explanation":"Uma associação descreve variação conjunta, mas não isola a direção causal nem outros fatores que possam influenciar os dois indicadores.","errorFocus":"Transformar correlação em causa sem desenho de pesquisa ou evidência adicional.","hint":"Descreva o padrão e pergunte que outras variáveis e mecanismos podem explicá-lo.","misconceptions":{"A associação prova que cada ano adicional causou o mesmo aumento de renda.":["CORRELATION_AS_CAUSATION"],"O rendimento causou necessariamente todos os anos de estudo observados.":["CORRELATION_AS_CAUSATION"],"Não há relação possível porque a tabela contém dois indicadores.":["CORRELATION_AS_CAUSATION"]},"position":4},{"id":"v5-sociology-inequality-practice-01","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"CALCULATE","contextFamily":"CULTURAL_ACCESS_RATE","statement":"Em dados fictícios, 21 de 70 moradores do bairro P visitaram um centro cultural e 32 de 160 do bairro Q fizeram o mesmo. Qual bairro teve maior proporção?","options":["Q, porque 32 visitas é mais que 21.","P, com 30%, contra 20% em Q.","Os dois tiveram 21% porque 21 é o menor total.","Não é possível comparar proporções com os dados fornecidos."],"correctAnswer":"P, com 30%, contra 20% em Q.","explanation":"21/70 = 30%; 32/160 = 20%. O total de Q é maior, mas a participação relativa é menor.","errorFocus":"Escolher a maior contagem sem calcular a proporção.","hint":"Calcule participantes ÷ total do bairro em cada caso.","misconceptions":{"Q, porque 32 visitas é mais que 21.":["COUNT_CONFUSED_WITH_RATE"],"Os dois tiveram 21% porque 21 é o menor total.":["COUNT_CONFUSED_WITH_RATE"],"Não é possível comparar proporções com os dados fornecidos.":["COUNT_CONFUSED_WITH_RATE"]},"position":1},{"id":"v5-sociology-inequality-practice-02","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"PERCENTAGE_POINT_CHANGE","statement":"Uma série hipotética indica que a participação em uma atividade passou de 28% para 35%. Qual foi a variação em pontos percentuais?","options":["7% de aumento relativo.","25 pontos percentuais.","63 pontos percentuais.","7 pontos percentuais."],"correctAnswer":"7 pontos percentuais.","explanation":"A diferença em pontos percentuais é 35 − 28 = 7. O aumento relativo seria 7/28 = 25%, outra medida.","errorFocus":"Confundir diferença em pontos percentuais com variação relativa.","hint":"Subtraia os percentuais para pontos percentuais; divida pela base para variação relativa.","misconceptions":{"7% de aumento relativo.":["PERCENTAGE_POINT_CONFUSION"],"25 pontos percentuais.":["PERCENTAGE_POINT_CONFUSION"],"63 pontos percentuais.":["PERCENTAGE_POINT_CONFUSION"]},"position":2},{"id":"v5-sociology-inequality-practice-03","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"CALCULATE","contextFamily":"RELATIVE_RATE_CHANGE","statement":"Em um exemplo fictício, a taxa de acesso a uma biblioteca passou de 20% para 25%. Qual foi o aumento relativo em relação à taxa inicial?","options":["25%.","5%.","20%.","45%."],"correctAnswer":"25%.","explanation":"O aumento foi de 5 pontos percentuais; em relação à base inicial, 5/20 = 0,25, ou 25%.","errorFocus":"Usar a diferença de 5 pontos percentuais como se fosse a variação relativa.","hint":"Use a taxa inicial como denominador da variação relativa.","misconceptions":{"5%.":["BASE_OF_RELATIVE_CHANGE_IGNORED"],"20%.":["BASE_OF_RELATIVE_CHANGE_IGNORED"],"45%.":["BASE_OF_RELATIVE_CHANGE_IGNORED"]},"position":3},{"id":"v5-sociology-inequality-practice-04","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"INCOME_OUTLIER_SUMMARY","statement":"Uma distribuição fictícia de cinco rendimentos mensais é R$ 900, R$ 1.000, R$ 1.100, R$ 1.200 e R$ 5.800. Qual leitura da média e da mediana está correta?","options":["A média e a mediana são R$ 1.100.","A mediana é R$ 2.000 e representa o valor mais frequente.","A mediana é R$ 1.100; o valor alto puxa a média, que é R$ 2.000.","A média é R$ 5.800 porque é o maior valor."],"correctAnswer":"A mediana é R$ 1.100; o valor alto puxa a média, que é R$ 2.000.","explanation":"A soma é R$ 10.000, então a média é R$ 2.000. O terceiro valor ordenado é R$ 1.100, a mediana; o extremo eleva a média.","errorFocus":"Tratar média, mediana e valor extremo como medidas equivalentes.","hint":"Ordene os valores para achar a mediana e some os cinco para calcular a média.","misconceptions":{"A média e a mediana são R$ 1.100.":["MEAN_MEDIAN_EXTREME_CONFUSED"],"A mediana é R$ 2.000 e representa o valor mais frequente.":["MEAN_MEDIAN_EXTREME_CONFUSED"],"A média é R$ 5.800 porque é o maior valor.":["MEAN_MEDIAN_EXTREME_CONFUSED"]},"position":4},{"id":"v5-sociology-inequality-practice-05","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"CALCULATE","contextFamily":"PER_CAPITA_HOUSEHOLD_INCOME","statement":"Dois domicílios fictícios recebem, juntos, R$ 12.000 e R$ 18.000 por mês. O primeiro tem 3 moradores e o segundo, 6. Qual tem maior rendimento domiciliar per capita?","options":["O segundo, pois o total recebido é maior.","Os dois, pois os rendimentos totais somam R$ 30.000.","Não se pode calcular sem saber a profissão dos moradores.","O primeiro: R$ 4.000 por pessoa, contra R$ 3.000 no segundo."],"correctAnswer":"O primeiro: R$ 4.000 por pessoa, contra R$ 3.000 no segundo.","explanation":"R$ 12.000/3 = R$ 4.000; R$ 18.000/6 = R$ 3.000. O denominador é o número de moradores.","errorFocus":"Confundir renda total do domicílio com renda por pessoa.","hint":"Divida o total de cada domicílio pelo respectivo número de moradores.","misconceptions":{"O segundo, pois o total recebido é maior.":["TOTAL_CONFUSED_WITH_PER_CAPITA"],"Os dois, pois os rendimentos totais somam R$ 30.000.":["TOTAL_CONFUSED_WITH_PER_CAPITA"],"Não se pode calcular sem saber a profissão dos moradores.":["TOTAL_CONFUSED_WITH_PER_CAPITA"]},"position":5},{"id":"v5-sociology-inequality-practice-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"ABSOLUTE_GAP_MEDIAN","statement":"Em duas localidades fictícias, a mediana de uma medida de renda é R$ 2.400 em A e R$ 1.900 em B. Qual é a diferença absoluta entre as medianas?","options":["R$ 1.900.","R$ 500.","R$ 2.400.","26,3 pontos percentuais."],"correctAnswer":"R$ 500.","explanation":"A diferença absoluta é 2.400 − 1.900 = R$ 500. Não é uma porcentagem nem descreve a distribuição inteira.","errorFocus":"Chamar uma diferença monetária de percentual ou interpretar uma mediana como média.","hint":"Subtraia os dois valores mantendo a mesma unidade monetária.","misconceptions":{"R$ 1.900.":["ABSOLUTE_RELATIVE_GAP_CONFUSED"],"R$ 2.400.":["ABSOLUTE_RELATIVE_GAP_CONFUSED"],"26,3 pontos percentuais.":["ABSOLUTE_RELATIVE_GAP_CONFUSED"]},"position":6},{"id":"v5-sociology-inequality-practice-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"RATE_DEFINITION_ALIGNMENT","statement":"Um relatório define “acesso” como ter utilizado um serviço ao menos uma vez no mês. Outro define como possuir cadastro, mesmo sem uso. O que fazer antes de comparar as taxas?","options":["Comparar os percentuais porque ambos usam a palavra “acesso”.","Escolher o maior percentual como mais confiável.","Verificar as definições e harmonizá-las ou declarar que não são diretamente comparáveis.","Somar as taxas para obter um indicador único."],"correctAnswer":"Verificar as definições e harmonizá-las ou declarar que não são diretamente comparáveis.","explanation":"O mesmo rótulo pode representar variáveis diferentes. A definição operacional precisa coincidir ou a comparação deve explicitar a diferença.","errorFocus":"Supor que nomes iguais garantem medidas iguais.","hint":"Leia como cada indicador foi operacionalizado antes de colocar os números lado a lado.","misconceptions":{"Comparar os percentuais porque ambos usam a palavra “acesso”.":["OPERATIONAL_DEFINITION_IGNORED"],"Escolher o maior percentual como mais confiável.":["OPERATIONAL_DEFINITION_IGNORED"],"Somar as taxas para obter um indicador único.":["OPERATIONAL_DEFINITION_IGNORED"]},"position":7},{"id":"v5-sociology-inequality-practice-08","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"CALCULATE","contextFamily":"DENOMINATOR_BY_GROUP","statement":"Uma tabela fictícia informa 18 participantes entre 60 pessoas no grupo R e 20 entre 100 no grupo S. Quais são as taxas?","options":["R: 30%; S: 20%.","R: 18%; S: 20%.","R: 60%; S: 100%.","R: 3%; S: 2%."],"correctAnswer":"R: 30%; S: 20%.","explanation":"18/60 = 0,30 e 20/100 = 0,20. Multiplicar por 100 expressa as razões em porcentagem.","errorFocus":"Usar os numeradores como percentuais ou inverter denominador e numerador.","hint":"Em cada grupo, divida participantes pelo total correspondente.","misconceptions":{"R: 18%; S: 20%.":["DENOMINATOR_MISMATCH"],"R: 60%; S: 100%.":["DENOMINATOR_MISMATCH"],"R: 3%; S: 2%.":["DENOMINATOR_MISMATCH"]},"position":8},{"id":"v5-sociology-inequality-practice-09","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"SAME_MEAN_DIFFERENT_SPREAD","statement":"Dois grupos fictícios têm a mesma renda média. No grupo A, os valores são próximos; no B, há valores muito baixos e muito altos. Qual conclusão é adequada?","options":["A média igual não mostra que as distribuições ou as experiências dos grupos sejam iguais.","Os dois grupos têm necessariamente a mesma mediana.","A dispersão não importa se a média coincide.","O grupo B não apresenta desigualdade interna."],"correctAnswer":"A média igual não mostra que as distribuições ou as experiências dos grupos sejam iguais.","explanation":"A média resume o centro aritmético, mas não a dispersão nem a forma da distribuição. É preciso examinar outras medidas ou os dados desagregados.","errorFocus":"Inferir igualdade distributiva a partir de uma média igual.","hint":"Pergunte quais valores e dispersões diferentes podem produzir a mesma média.","misconceptions":{"Os dois grupos têm necessariamente a mesma mediana.":["AGGREGATE_AS_INDIVIDUAL_DISTRIBUTION"],"A dispersão não importa se a média coincide.":["AGGREGATE_AS_INDIVIDUAL_DISTRIBUTION"],"O grupo B não apresenta desigualdade interna.":["AGGREGATE_AS_INDIVIDUAL_DISTRIBUTION"]},"position":9},{"id":"v5-sociology-inequality-practice-10","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"DAYTIME_MARKET_SAMPLE","statement":"Uma equipe entrevista apenas pessoas que passam por uma feira entre 10h e 12h para estimar a rotina de trabalho de toda uma cidade. Qual é o principal limite?","options":["A amostra é representativa porque a feira é pública.","O resultado prova que ninguém trabalha nesse horário.","O horário e o local podem excluir grupos com outras rotinas; a amostra pode ser enviesada.","A quantidade de entrevistados elimina a cobertura desigual."],"correctAnswer":"O horário e o local podem excluir grupos com outras rotinas; a amostra pode ser enviesada.","explanation":"Pessoas que não frequentam a feira ou trabalham nesse horário têm menor chance de inclusão. O método restringe a população observada.","errorFocus":"Ignorar quem não teve oportunidade de entrar na amostra.","hint":"Mapeie quem poderia ser selecionado e quem ficou de fora pelo local e horário.","misconceptions":{"A amostra é representativa porque a feira é pública.":["COVERAGE_BIAS_IGNORED"],"O resultado prova que ninguém trabalha nesse horário.":["COVERAGE_BIAS_IGNORED"],"A quantidade de entrevistados elimina a cobertura desigual.":["COVERAGE_BIAS_IGNORED"]},"position":10},{"id":"v5-sociology-inequality-practice-11","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"UNCHANGED_AVERAGE_COMPOSITION","statement":"Uma média municipal fica estável entre dois anos fictícios, mas a população observada muda de composição. O que é necessário antes de concluir que as condições individuais não mudaram?","options":["Concluir que todas as pessoas mantiveram o mesmo rendimento.","Examinar grupos, distribuições e composição; a média agregada estável pode ocultar mudanças.","Afirmar que a medição está errada porque a média não mudou.","Desconsiderar a composição, pois médias sempre neutralizam diferenças entre grupos."],"correctAnswer":"Examinar grupos, distribuições e composição; a média agregada estável pode ocultar mudanças.","explanation":"Uma média estável não implica trajetórias individuais estáveis. Mudanças na composição podem compensar variações entre subgrupos.","errorFocus":"Tomar uma estatística agregada como descrição de cada pessoa ou grupo.","hint":"Desagregue os valores e compare a composição dos dois períodos.","misconceptions":{"Concluir que todas as pessoas mantiveram o mesmo rendimento.":["AGGREGATE_HIDES_COMPOSITION"],"Afirmar que a medição está errada porque a média não mudou.":["AGGREGATE_HIDES_COMPOSITION"],"Desconsiderar a composição, pois médias sempre neutralizam diferenças entre grupos.":["AGGREGATE_HIDES_COMPOSITION"]},"position":11},{"id":"v5-sociology-inequality-practice-12","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"BASIC_NEEDS_MULTI_INDICATOR","statement":"Um painel fictício mostra renda média igual em dois bairros, mas tempos de deslocamento e acesso à água diferem. Qual leitura é mais apropriada?","options":["A renda média prova que a qualidade de vida é igual.","Tempo de deslocamento não pode ser tratado como dado social.","Uma diferença em qualquer indicador prova a causa de todas as demais.","A renda média é apenas uma dimensão; outras condições devem ser analisadas separadamente."],"correctAnswer":"A renda média é apenas uma dimensão; outras condições devem ser analisadas separadamente.","explanation":"Indicadores captam dimensões distintas. A média de renda não resume acesso a serviços, mobilidade ou distribuição intrabairro.","errorFocus":"Reduzir desigualdade e condições de vida a um único indicador.","hint":"Identifique a dimensão medida por cada coluna e evite fundi-las sem justificativa.","misconceptions":{"A renda média prova que a qualidade de vida é igual.":["SINGLE_INDICATOR_TOTALIZATION"],"Tempo de deslocamento não pode ser tratado como dado social.":["SINGLE_INDICATOR_TOTALIZATION"],"Uma diferença em qualquer indicador prova a causa de todas as demais.":["SINGLE_INDICATOR_TOTALIZATION"]},"position":12},{"id":"v5-sociology-inequality-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"CALCULATE","contextFamily":"APPLICATIONS_BY_POPULATION","statement":"Em um registro fictício, 48 de 120 famílias de uma região e 55 de 220 de outra solicitaram um benefício. Qual região teve maior taxa de solicitação?","options":["A segunda, porque 55 solicitações é mais que 48.","As taxas são iguais porque ambas têm mais de 100 famílias.","A primeira: 40%, contra 25% na segunda.","A primeira: 48%, contra 55% na segunda."],"correctAnswer":"A primeira: 40%, contra 25% na segunda.","explanation":"48/120 = 40%; 55/220 = 25%. A comparação proporcional responde melhor à participação relativa.","errorFocus":"Comparar números absolutos quando os totais regionais diferem.","hint":"Calcule cada razão com o total de famílias da mesma região.","misconceptions":{"A segunda, porque 55 solicitações é mais que 48.":["COUNT_CONFUSED_WITH_RATE"],"As taxas são iguais porque ambas têm mais de 100 famílias.":["COUNT_CONFUSED_WITH_RATE"],"A primeira: 48%, contra 55% na segunda.":["COUNT_CONFUSED_WITH_RATE"]},"position":1},{"id":"v5-sociology-inequality-transfer-02","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"PROGRAM_BEFORE_AFTER_NO_CONTROL","statement":"Após uma oficina fictícia, a taxa de participação de um bairro aumentou. Não houve grupo de comparação nem informação sobre mudanças simultâneas. O que os dados sustentam?","options":["A oficina causou todo o aumento.","Houve aumento observado depois da oficina, mas não basta para atribuí-lo à oficina.","A oficina não teve efeito porque não houve grupo de controle.","O aumento prova que a desigualdade foi eliminada."],"correctAnswer":"Houve aumento observado depois da oficina, mas não basta para atribuí-lo à oficina.","explanation":"A sequência temporal é compatível com efeito, mas outras mudanças podem explicar o aumento. Sem comparação ou evidências adicionais, causalidade não está identificada.","errorFocus":"Confundir “depois de” com “por causa de”.","hint":"Separe a mudança observada da atribuição causal e liste explicações alternativas.","misconceptions":{"A oficina causou todo o aumento.":["POST_HOC_CAUSALITY"],"A oficina não teve efeito porque não houve grupo de controle.":["POST_HOC_CAUSALITY"],"O aumento prova que a desigualdade foi eliminada.":["POST_HOC_CAUSALITY"]},"position":2},{"id":"v5-sociology-inequality-transfer-03","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"TRUNCATED_AXIS_RATE_CHART","statement":"Um gráfico fictício mostra taxas de 48% e 52%, mas o eixo vertical começa em 45%. Qual cuidado é necessário?","options":["A diferença é de 52 pontos percentuais.","O gráfico prova que um grupo é duas vezes maior.","A comparação é inválida em qualquer gráfico que não comece em zero.","A escala truncada pode ampliar visualmente a diferença; leia valores e eixo."],"correctAnswer":"A escala truncada pode ampliar visualmente a diferença; leia valores e eixo.","explanation":"A diferença é de 4 pontos percentuais. Um eixo truncado pode exagerar a distância visual, embora os valores continuem legíveis.","errorFocus":"Inferir magnitude pelo comprimento visual das barras sem ler a escala.","hint":"Confira início, intervalo e unidade do eixo antes de interpretar a diferença.","misconceptions":{"A diferença é de 52 pontos percentuais.":["TRUNCATED_AXIS_MAGNITUDE"],"O gráfico prova que um grupo é duas vezes maior.":["TRUNCATED_AXIS_MAGNITUDE"],"A comparação é inválida em qualquer gráfico que não comece em zero.":["TRUNCATED_AXIS_MAGNITUDE"]},"position":3},{"id":"v5-sociology-inequality-transfer-04","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"INTERPRET","contextFamily":"GINI_AND_MEAN_DISTINCT","statement":"Dois relatórios fictícios para a mesma população apresentam Gini menor em um deles, mas não informam média ou mediana. O que não se pode concluir?","options":["Que a renda média seja maior no relatório com Gini menor.","Que a medida de desigualdade reportada é menor, se definições e escopos forem iguais.","Que o Gini resume a desigualdade relativa da distribuição medida.","Que é preciso consultar outros indicadores para conhecer o nível de renda."],"correctAnswer":"Que a renda média seja maior no relatório com Gini menor.","explanation":"O Gini informa desigualdade da distribuição, não o nível médio de renda. Uma distribuição pode ser menos desigual e ainda ter renda média menor.","errorFocus":"Deduzir o nível de renda a partir de uma medida de desigualdade.","hint":"Separe “como a renda se distribui” de “qual é seu nível médio”.","misconceptions":{"Que a medida de desigualdade reportada é menor, se definições e escopos forem iguais.":["GINI_MEASURE_MISREAD"],"Que o Gini resume a desigualdade relativa da distribuição medida.":["GINI_MEASURE_MISREAD"],"Que é preciso consultar outros indicadores para conhecer o nível de renda.":["GINI_MEASURE_MISREAD"]},"position":4},{"id":"v5-sociology-inequality-transfer-05","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"GROUP_RATE_TO_INDIVIDUAL","statement":"Uma tabela fictícia informa que 35% de um grupo e 20% de outro usaram um serviço. Qual inferência extrapola os dados?","options":["Descrever que as proporções observadas diferem nos grupos pesquisados.","Afirmar que cada pessoa do primeiro grupo tem maior probabilidade individual por uma característica pessoal inerente.","Perguntar sobre acesso, seleção e condições sociais que possam influenciar o padrão.","Verificar tamanho, período e método antes de generalizar."],"correctAnswer":"Afirmar que cada pessoa do primeiro grupo tem maior probabilidade individual por uma característica pessoal inerente.","explanation":"Uma diferença agregada não determina o comportamento ou a probabilidade de cada indivíduo, nem identifica uma causa inerente.","errorFocus":"Transferir automaticamente uma associação entre grupos para cada integrante.","hint":"Diferencie a taxa do grupo das características de uma pessoa específica.","misconceptions":{"Descrever que as proporções observadas diferem nos grupos pesquisados.":["ECOLOGICAL_INFERENCE"],"Perguntar sobre acesso, seleção e condições sociais que possam influenciar o padrão.":["ECOLOGICAL_INFERENCE"],"Verificar tamanho, período e método antes de generalizar.":["ECOLOGICAL_INFERENCE"]},"position":5},{"id":"v5-sociology-inequality-transfer-06","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"CROSS_TABULATED_ACCESS","statement":"Uma pesquisa fictícia desagrega acesso a um curso por território e faixa de renda. As taxas diferem entre alguns cruzamentos. Qual próximo passo melhora a análise sem atribuir causas precipitadamente?","options":["Comparar definições, denominadores e subgrupos e investigar mecanismos com evidências adicionais.","Declarar que território sozinho causou todas as diferenças.","Somar as taxas dos cruzamentos e chamar o resultado de média.","Atribuir as diferenças exclusivamente ao esforço individual."],"correctAnswer":"Comparar definições, denominadores e subgrupos e investigar mecanismos com evidências adicionais.","explanation":"A desagregação revela padrões que o total pode ocultar, mas não controla automaticamente seleção, condições simultâneas ou mecanismos causais.","errorFocus":"Tratar cruzamentos descritivos como prova causal ou somar percentuais incompatíveis.","hint":"Leia cada denominador e recorte; depois formule perguntas explicativas testáveis.","misconceptions":{"Declarar que território sozinho causou todas as diferenças.":["CROSS_TAB_CAUSAL_OVERCLAIM"],"Somar as taxas dos cruzamentos e chamar o resultado de média.":["CROSS_TAB_CAUSAL_OVERCLAIM"],"Atribuir as diferenças exclusivamente ao esforço individual.":["CROSS_TAB_CAUSAL_OVERCLAIM"]},"position":6},{"id":"v5-sociology-inequality-transfer-07","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"NONRESPONSE_BY_GROUP","statement":"Em uma pesquisa fictícia, a taxa de resposta é 90% em um grupo e 45% em outro. Que verificação é especialmente importante?","options":["Ignorar a diferença porque ambos os grupos receberam o questionário.","Substituir todas as respostas ausentes por zero.","Concluir que o grupo de menor resposta tem menor indicador.","Investigar se a não resposta está relacionada às condições medidas e se altera a comparação."],"correctAnswer":"Investigar se a não resposta está relacionada às condições medidas e se altera a comparação.","explanation":"Quando a chance de responder varia entre grupos, os respondentes podem não representar cada grupo da mesma forma; isso pode enviesar a comparação.","errorFocus":"Tratar ausência de resposta como valor zero ou ausência aleatória sem evidência.","hint":"Compare taxas de resposta e perfil de respondentes e não respondentes, se disponível.","misconceptions":{"Ignorar a diferença porque ambos os grupos receberam o questionário.":["NONRESPONSE_ASSUMED_RANDOM"],"Substituir todas as respostas ausentes por zero.":["NONRESPONSE_ASSUMED_RANDOM"],"Concluir que o grupo de menor resposta tem menor indicador.":["NONRESPONSE_ASSUMED_RANDOM"]},"position":7},{"id":"v5-sociology-inequality-transfer-08","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"DESCRIPTIVE_NORMATIVE_CLAIM","statement":"Uma tabela fictícia mostra diferença de acesso a um serviço. Qual conclusão exige um juízo normativo além da descrição?","options":["Dizer que os percentuais observados são diferentes.","Indicar quais grupos e período foram comparados.","Dizer que a diferença é injusta, sem explicitar critério ou contexto para avaliar justiça.","Solicitar dados adicionais sobre barreiras e critérios de acesso."],"correctAnswer":"Dizer que a diferença é injusta, sem explicitar critério ou contexto para avaliar justiça.","explanation":"A desigualdade observada é uma descrição. Avaliar justiça requer explicitar princípios, direitos ou critérios normativos e contextualizar a situação.","errorFocus":"Confundir constatação estatística com avaliação ética ou política.","hint":"Separe a frase que descreve o dado da frase que julga o que deveria ocorrer.","misconceptions":{"Dizer que os percentuais observados são diferentes.":["DESCRIPTIVE_NORMATIVE_CONFUSION"],"Indicar quais grupos e período foram comparados.":["DESCRIPTIVE_NORMATIVE_CONFUSION"],"Solicitar dados adicionais sobre barreiras e critérios de acesso.":["DESCRIPTIVE_NORMATIVE_CONFUSION"]},"position":8},{"id":"v5-sociology-inequality-lock-01","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"DIAGNOSE","contextFamily":"DENOMINATOR_SWAP_WAVE","statement":"Uma pesquisa fictícia teve 40 atendimentos em 100 pessoas no mês 1 e 45 em 150 no mês 2. Um resumo diz “a taxa subiu porque 45 é maior que 40”. Qual correção é adequada?","options":["A taxa subiu de 40% para 45%.","A taxa ficou em 5% nos dois meses.","Não existe denominador para calcular.","A taxa caiu de 40% para 30%; as contagens, sozinhas, não mostram aumento da taxa."],"correctAnswer":"A taxa caiu de 40% para 30%; as contagens, sozinhas, não mostram aumento da taxa.","explanation":"Mês 1: 40/100 = 40%; mês 2: 45/150 = 30%. O total de atendimentos aumentou, mas a proporção diminuiu.","errorFocus":"Confundir mudança da contagem com mudança da taxa.","hint":"Calcule atendimentos ÷ pessoas observadas em cada mês.","misconceptions":{"A taxa subiu de 40% para 45%.":["DENOMINATOR_CHANGE_IGNORED"],"A taxa ficou em 5% nos dois meses.":["DENOMINATOR_CHANGE_IGNORED"],"Não existe denominador para calcular.":["DENOMINATOR_CHANGE_IGNORED"]},"position":1},{"id":"v5-sociology-inequality-lock-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"NONRESPONSE_ESTIMATE","statement":"Um questionário fictício registra 70 respostas favoráveis entre 100 retornos, mas foi enviado a 500 pessoas. Qual afirmação é mais defensável?","options":["70% das 500 pessoas foram favoráveis.","430 pessoas foram contrárias.","70% dos respondentes foram favoráveis; a opinião dos 500 não pode ser estimada sem tratar a não resposta.","A pesquisa comprova aprovação de toda a população."],"correctAnswer":"70% dos respondentes foram favoráveis; a opinião dos 500 não pode ser estimada sem tratar a não resposta.","explanation":"70/100 = 70% entre quem respondeu. As 400 não respostas não podem ser classificadas como favoráveis ou contrárias.","errorFocus":"Usar os retornos como se fossem todas as pessoas contatadas.","hint":"Declare o denominador exato de cada percentual e não preencha ausências por suposição.","misconceptions":{"70% das 500 pessoas foram favoráveis.":["NONRESPONSE_AS_NEGATIVE_OR_POSITIVE"],"430 pessoas foram contrárias.":["NONRESPONSE_AS_NEGATIVE_OR_POSITIVE"],"A pesquisa comprova aprovação de toda a população.":["NONRESPONSE_AS_NEGATIVE_OR_POSITIVE"]},"position":2},{"id":"v5-sociology-inequality-lock-03","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"GROUP_AVERAGE_PERSON","statement":"Uma média fictícia de rendimento de um grupo é R$ 3.000. O que ela informa sobre uma integrante específica?","options":["Nada conclusivo sobre o rendimento dela sem dados individuais ou outra informação adequada.","Que ela recebe exatamente R$ 3.000.","Que metade das pessoas recebe mais que R$ 3.000.","Que não existe desigualdade dentro do grupo."],"correctAnswer":"Nada conclusivo sobre o rendimento dela sem dados individuais ou outra informação adequada.","explanation":"A média é um resumo do grupo; pessoas individuais podem estar acima ou abaixo. Para afirmar algo sobre a integrante, seriam necessários dados apropriados.","errorFocus":"Atribuir a cada pessoa o valor agregado do grupo.","hint":"Diferencie unidade de análise: média grupal não é observação individual.","misconceptions":{"Que ela recebe exatamente R$ 3.000.":["AGGREGATE_AS_INDIVIDUAL_DISTRIBUTION"],"Que metade das pessoas recebe mais que R$ 3.000.":["AGGREGATE_AS_INDIVIDUAL_DISTRIBUTION"],"Que não existe desigualdade dentro do grupo.":["AGGREGATE_AS_INDIVIDUAL_DISTRIBUTION"]},"position":3},{"id":"v5-sociology-inequality-lock-04","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"GENDER_GAP_CONFOUNDERS","statement":"Uma série fictícia mostra rendimentos médios diferentes por grupo de gênero, mas não controla ocupação, jornada ou setor. O que os dados permitem?","options":["Atribuir toda a diferença a uma única causa comprovada.","Descrever a diferença observada e apontar que esses fatores podem ser investigados; não isolam uma causa.","Afirmar que os grupos têm a mesma distribuição individual.","Concluir que diferenças ocupacionais são impossíveis."],"correctAnswer":"Descrever a diferença observada e apontar que esses fatores podem ser investigados; não isolam uma causa.","explanation":"A comparação agregada registra um padrão, mas fatores como ocupação e jornada podem estar relacionados. A tabela descrita não separa seus efeitos.","errorFocus":"Atribuir causalidade exclusiva sem controlar explicações concorrentes.","hint":"Escreva primeiro a diferença observada e depois liste fatores não medidos.","misconceptions":{"Atribuir toda a diferença a uma única causa comprovada.":["OMITTED_VARIABLE_CAUSALITY"],"Afirmar que os grupos têm a mesma distribuição individual.":["OMITTED_VARIABLE_CAUSALITY"],"Concluir que diferenças ocupacionais são impossíveis.":["OMITTED_VARIABLE_CAUSALITY"]},"position":4},{"id":"v5-sociology-inequality-lock-05","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"SAMPLING_FRAME_COVERAGE","statement":"Uma estimativa fictícia de acesso digital é feita somente com respostas recebidas pelo aplicativo do serviço. Qual risco de método aparece?","options":["Pessoas sem acesso ao próprio aplicativo podem ficar fora da amostra, subestimando barreiras digitais.","O aplicativo garante cobertura universal.","Quem não respondeu deve ser contado como tendo acesso.","O método prova que acesso digital depende apenas de escolha pessoal."],"correctAnswer":"Pessoas sem acesso ao próprio aplicativo podem ficar fora da amostra, subestimando barreiras digitais.","explanation":"Selecionar participantes pelo canal que está sendo avaliado pode excluir quem enfrenta a barreira mais relevante.","errorFocus":"Ignorar que o cadastro ou canal de coleta pode excluir parte da população.","hint":"Pergunte se a forma de alcançar participantes depende do indicador investigado.","misconceptions":{"O aplicativo garante cobertura universal.":["SAMPLING_FRAME_EXCLUDES_TARGET"],"Quem não respondeu deve ser contado como tendo acesso.":["SAMPLING_FRAME_EXCLUDES_TARGET"],"O método prova que acesso digital depende apenas de escolha pessoal.":["SAMPLING_FRAME_EXCLUDES_TARGET"]},"position":5},{"id":"v5-sociology-inequality-lock-06","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"GINI_RANGE_AND_MEAN","statement":"Um exercício fictício apresenta Gini 0,31 e Gini 0,47, calculados para a mesma população e definição. Qual leitura é correta?","options":["0,47 significa que 47% da população é pobre.","0,31 significa renda média de 31 unidades monetárias.","0,47 comprova que cada pessoa do grupo tem mais renda.","0,31 indica menor desigualdade relativa medida; nenhum dos valores informa sozinho a renda média."],"correctAnswer":"0,31 indica menor desigualdade relativa medida; nenhum dos valores informa sozinho a renda média.","explanation":"O Gini é um coeficiente de desigualdade da distribuição. Não é percentual de pobreza nem valor de renda média.","errorFocus":"Ler o coeficiente como porcentagem de pessoas ou valor monetário.","hint":"Identifique escala, objeto medido e limites do indicador antes de interpretar.","misconceptions":{"0,47 significa que 47% da população é pobre.":["GINI_AS_PERCENTAGE_OR_INCOME"],"0,31 significa renda média de 31 unidades monetárias.":["GINI_AS_PERCENTAGE_OR_INCOME"],"0,47 comprova que cada pessoa do grupo tem mais renda.":["GINI_AS_PERCENTAGE_OR_INCOME"]},"position":6},{"id":"v5-sociology-inequality-review-01","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"CALCULATE","contextFamily":"SPORTS_PROGRAM_DENOMINATOR","statement":"Em dados fictícios, 15 de 50 participantes do grupo A e 18 de 90 do grupo B concluíram uma etapa. Quais taxas são corretas?","options":["A: 15%; B: 18%.","A: 30%; B: 20%.","A: 50%; B: 90%.","A: 3%; B: 2%."],"correctAnswer":"A: 30%; B: 20%.","explanation":"15/50 = 30% e 18/90 = 20%. O denominador de cada taxa é o total do próprio grupo.","errorFocus":"Transformar contagens em percentuais sem usar os denominadores.","hint":"Divida o número que concluiu pelo número de participantes de cada grupo.","misconceptions":{"A: 15%; B: 18%.":["DENOMINATOR_MISMATCH"],"A: 50%; B: 90%.":["DENOMINATOR_MISMATCH"],"A: 3%; B: 2%.":["DENOMINATOR_MISMATCH"]},"position":1},{"id":"v5-sociology-inequality-review-02","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"SHELTER_ACCESS_COMPARISON","statement":"Em levantamento fictício, 30 de 120 famílias de uma área e 42 de 210 de outra acessaram um serviço. Qual área teve maior taxa?","options":["A segunda, pois 42 é maior que 30.","As duas, pois as contagens são próximas.","A primeira, com 25%, contra 20% na segunda.","A segunda, com 20 pontos percentuais a mais."],"correctAnswer":"A primeira, com 25%, contra 20% na segunda.","explanation":"30/120 = 25%; 42/210 = 20%. A diferença é de 5 pontos percentuais, a favor da primeira área.","errorFocus":"Comparar os totais observados e concluir sem calcular taxas.","hint":"Calcule cada fração e depois compare os percentuais.","misconceptions":{"A segunda, pois 42 é maior que 30.":["COUNT_CONFUSED_WITH_RATE"],"As duas, pois as contagens são próximas.":["COUNT_CONFUSED_WITH_RATE"],"A segunda, com 20 pontos percentuais a mais.":["COUNT_CONFUSED_WITH_RATE"]},"position":2},{"id":"v5-sociology-inequality-review-03","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"CALCULATE","contextFamily":"INCOME_SHARE_RELATIVE_CHANGE","statement":"Uma taxa fictícia de participação passou de 12% para 15%. Qual é a variação relativa, usando 12% como base?","options":["3%.","12,5%.","25%.","27%."],"correctAnswer":"25%.","explanation":"A diferença é 3 pontos percentuais; 3/12 = 0,25, ou 25% de aumento relativo.","errorFocus":"Usar a diferença em pontos percentuais como variação relativa.","hint":"Divida o aumento pela taxa inicial antes de converter em porcentagem.","misconceptions":{"3%.":["BASE_OF_RELATIVE_CHANGE_IGNORED"],"12,5%.":["BASE_OF_RELATIVE_CHANGE_IGNORED"],"27%.":["BASE_OF_RELATIVE_CHANGE_IGNORED"]},"position":3},{"id":"v5-sociology-inequality-review-04","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"MEDIAN_OUTLIER_REVIEW","statement":"Cinco valores fictícios são 1.000, 1.100, 1.200, 1.300 e 6.400. Qual é a mediana e o que o último valor faz à média?","options":["A mediana é 2.200, igual à média.","A mediana é 6.400 porque é o maior valor.","A média permanece 1.200 porque a mediana não muda.","A mediana é 1.200; o valor alto eleva a média acima da mediana."],"correctAnswer":"A mediana é 1.200; o valor alto eleva a média acima da mediana.","explanation":"O valor central ordenado é 1.200. A média é 11.000/5 = 2.200, elevada pelo valor extremo de 6.400.","errorFocus":"Achar mediana sem ordenar ou supor que ela determina a média.","hint":"Ordene os dados para a mediana; calcule soma ÷ quantidade para a média.","misconceptions":{"A mediana é 2.200, igual à média.":["MEAN_MEDIAN_EXTREME_CONFUSED"],"A mediana é 6.400 porque é o maior valor.":["MEAN_MEDIAN_EXTREME_CONFUSED"],"A média permanece 1.200 porque a mediana não muda.":["MEAN_MEDIAN_EXTREME_CONFUSED"]},"position":4},{"id":"v5-sociology-inequality-review-05","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"INCOME_AND_SERVICE_ACCESS","statement":"Uma tabela fictícia cruza faixas de renda e acesso a um serviço. As taxas diferem, mas o relatório não informa como os grupos foram selecionados. Qual síntese respeita os dados?","options":["A renda, sozinha, causou toda diferença.","Há diferenças observadas entre as faixas pesquisadas; seleção e outros fatores limitam explicações gerais.","O acesso individual de cada pessoa segue exatamente a taxa de seu grupo.","A tabela é inútil porque não prova causalidade."],"correctAnswer":"Há diferenças observadas entre as faixas pesquisadas; seleção e outros fatores limitam explicações gerais.","explanation":"A tabela permite descrever diferenças no recorte observado. O método de seleção e variáveis adicionais precisam ser examinados antes de generalizar ou atribuir causa.","errorFocus":"Achar que dado sem causalidade não descreve padrão, ou extrapolar além da amostra.","hint":"Escreva uma conclusão descritiva e uma pergunta de método ou mecanismo que permaneça aberta.","misconceptions":{"A renda, sozinha, causou toda diferença.":["SCOPE_AND_CAUSALITY_OVERCLAIM"],"O acesso individual de cada pessoa segue exatamente a taxa de seu grupo.":["SCOPE_AND_CAUSALITY_OVERCLAIM"],"A tabela é inútil porque não prova causalidade.":["SCOPE_AND_CAUSALITY_OVERCLAIM"]},"position":5},{"id":"v5-sociology-inequality-review-06","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"SOURCE_METADATA_PERIOD","statement":"Dois painéis fictícios apresentam a taxa “acesso à moradia”, um para 2018 e outro para 2024, mas usam definições e populações diferentes. O que deve ser feito?","options":["Comparar apenas após harmonizar os critérios ou explicitar que as medidas não são diretamente comparáveis.","Subtrair os percentuais porque o nome do indicador é igual.","Somar os dois resultados para obter a taxa do período.","Considerar que qualquer diferença decorre do ano."],"correctAnswer":"Comparar apenas após harmonizar os critérios ou explicitar que as medidas não são diretamente comparáveis.","explanation":"Nome idêntico não garante comparabilidade. População, definição e método precisam coincidir ou as diferenças devem ser contextualizadas.","errorFocus":"Supor que rótulo igual torna medidas equivalentes.","hint":"Confira definição, universo, período e método em ambos os painéis.","misconceptions":{"Subtrair os percentuais porque o nome do indicador é igual.":["COMPARABILITY_METADATA_IGNORED"],"Somar os dois resultados para obter a taxa do período.":["COMPARABILITY_METADATA_IGNORED"],"Considerar que qualquer diferença decorre do ano.":["COMPARABILITY_METADATA_IGNORED"]},"position":6},{"id":"v5-sociology-inequality-review-07","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"AREA_TOTAL_VERSUS_RATE","statement":"Um distrito fictício registra 90 ocorrências em 900 moradores; outro, 50 em 250. Qual teve maior taxa por morador?","options":["O primeiro porque 90 ocorrências é o maior total.","O segundo: 50%, contra 90% no primeiro.","As taxas são iguais porque ambos registraram ocorrências.","O segundo: 20%, contra 10% no primeiro."],"correctAnswer":"O segundo: 20%, contra 10% no primeiro.","explanation":"90/900 = 10%; 50/250 = 20%. O distrito com menos ocorrências absolutas tem maior taxa no recorte.","errorFocus":"Confundir volume total com frequência relativa.","hint":"Divida ocorrências pelo tamanho da população de cada distrito.","misconceptions":{"O primeiro porque 90 ocorrências é o maior total.":["COUNT_CONFUSED_WITH_RATE"],"O segundo: 50%, contra 90% no primeiro.":["COUNT_CONFUSED_WITH_RATE"],"As taxas são iguais porque ambos registraram ocorrências.":["COUNT_CONFUSED_WITH_RATE"]},"position":7},{"id":"v5-sociology-inequality-review-08","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"GINI_VERSUS_POVERTY_RATE","statement":"Uma tabela fictícia informa que o Gini caiu, mas não mostra quantas pessoas estão abaixo de uma linha de pobreza. O que falta para avaliar pobreza?","options":["Um indicador de pobreza com definição, população e período explícitos.","O Gini, pois ele já informa o percentual abaixo da linha.","Apenas a média de renda, que substitui qualquer indicador distributivo.","A diferença entre os dois valores de Gini como número de pessoas."],"correctAnswer":"Um indicador de pobreza com definição, população e período explícitos.","explanation":"Desigualdade relativa e pobreza são conceitos relacionados, mas não idênticos. O coeficiente não informa diretamente quantas pessoas estão abaixo de uma linha.","errorFocus":"Usar um indicador de distribuição como substituto de uma medida de pobreza.","hint":"Pergunte qual variável responde diretamente à pergunta sobre a linha de pobreza.","misconceptions":{"O Gini, pois ele já informa o percentual abaixo da linha.":["GINI_AS_POVERTY_RATE"],"Apenas a média de renda, que substitui qualquer indicador distributivo.":["GINI_AS_POVERTY_RATE"],"A diferença entre os dois valores de Gini como número de pessoas.":["GINI_AS_POVERTY_RATE"]},"position":8},{"id":"v5-sociology-inequality-review-09","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"POLICY_EVALUATION_COMPARISON","statement":"Uma região fictícia implantou uma política e sua taxa mudou; uma região semelhante não implantou e ficou estável, mas a seleção não foi aleatória. Qual conclusão é mais responsável?","options":["A política está provada como causa única.","A comparação não oferece informação alguma.","A comparação fortalece a investigação do efeito, mas diferenças entre regiões ainda podem explicar parte da mudança.","A estabilidade da outra região demonstra que todos os fatores foram controlados."],"correctAnswer":"A comparação fortalece a investigação do efeito, mas diferenças entre regiões ainda podem explicar parte da mudança.","explanation":"Um comparador ajuda a avaliar mudança, mas sem aleatorização ou controles suficientes podem persistir diferenças prévias e fatores concorrentes.","errorFocus":"Tratar uma comparação observacional como controle perfeito.","hint":"Reconheça o que o grupo comparador acrescenta e quais diferenças ainda podem enviesar a inferência.","misconceptions":{"A política está provada como causa única.":["COMPARISON_GROUP_AS_PERFECT_CONTROL"],"A comparação não oferece informação alguma.":["COMPARISON_GROUP_AS_PERFECT_CONTROL"],"A estabilidade da outra região demonstra que todos os fatores foram controlados.":["COMPARISON_GROUP_AS_PERFECT_CONTROL"]},"position":9},{"id":"v5-sociology-inequality-review-10","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"MULTI_INDICATOR_FINAL_READING","statement":"Um painel fictício mostra Gini menor, média estável e uma taxa de acesso a serviços maior em um grupo do que em outro. Qual síntese é mais adequada?","options":["A média estável prova que todos mantiveram a renda.","Os indicadores descrevem dimensões distintas; a diferença observada não identifica, sozinha, causas nem experiências individuais.","O Gini menor garante que a pobreza desapareceu.","A taxa de acesso demonstra que cada integrante do grupo teve o serviço."],"correctAnswer":"Os indicadores descrevem dimensões distintas; a diferença observada não identifica, sozinha, causas nem experiências individuais.","explanation":"O Gini resume desigualdade da distribuição, a média resume nível central e a taxa mede acesso no recorte. Nenhum, isoladamente, descreve cada pessoa ou identifica causalidade.","errorFocus":"Fundir indicadores diferentes em uma única conclusão causal ou individual.","hint":"Nomeie o que cada coluna mede, o grupo observado e o limite de inferência.","misconceptions":{"A média estável prova que todos mantiveram a renda.":["INDICATOR_SCOPE_COLLAPSED"],"O Gini menor garante que a pobreza desapareceu.":["INDICATOR_SCOPE_COLLAPSED"],"A taxa de acesso demonstra que cada integrante do grupo teve o serviço.":["INDICATOR_SCOPE_COLLAPSED"]},"position":10}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 5, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-sociology-inequality-data-wave3',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 5
       and metadata->>'content_id' = 'v5-sociology-inequality-data-wave3' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'SOCIOLOGY', 'ESTRUTURA', 'analise_de_dados_de_desigualdade',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

commit;
